insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-start-alphabet','A1',null,'start','Алфавит и произношение','Абетка і вимова',1) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-abc-a','A1',null,'a1-start-alphabet','letter','A a — der Apfel','[а] — яблоко','[а] — яблуко',null,'Der Apfel ist rot.','Яблоко красное.','Яблуко червоне.',null,null,array[]::text[],1000),
('a1-abc-b','A1',null,'a1-start-alphabet','letter','B b — das Brot','[бэ] — хлеб','[бе] — хліб',null,'Ich kaufe Brot.','Я покупаю хлеб.','Я купую хліб.',null,null,array[]::text[],1001),
('a1-abc-c','A1',null,'a1-start-alphabet','letter','C c — das Café','[цэ] — кафе','[це] — кафе',null,'Wir gehen ins Café.','Мы идём в кафе.','Ми йдемо в кафе.',null,null,array[]::text[],1002),
('a1-abc-d','A1',null,'a1-start-alphabet','letter','D d — die Dusche','[дэ] — душ','[де] — душ',null,'Die Dusche ist kalt.','Душ холодный.','Душ холодний.',null,null,array[]::text[],1003),
('a1-abc-e','A1',null,'a1-start-alphabet','letter','E e — essen','[э] — есть (кушать)','[е] — їсти',null,'Wir essen um sieben.','Мы ужинаем в семь.','Ми вечеряємо о сьомій.',null,null,array[]::text[],1004),
('a1-abc-f','A1',null,'a1-start-alphabet','letter','F f — die Familie','[эф] — семья','[еф] — сім''я',null,'Meine Familie wohnt in Kiew.','Моя семья живёт в Киеве.','Моя сім''я живе в Києві.',null,null,array[]::text[],1005),
('a1-abc-g','A1',null,'a1-start-alphabet','letter','G g — gut','[гэ] — хорошо (твёрдое г)','[ґе] — добре (тверде ґ)',null,'Das ist gut.','Это хорошо.','Це добре.',null,null,array[]::text[],1006),
('a1-abc-h','A1',null,'a1-start-alphabet','letter','H h — das Haus','[ха] — дом (лёгкий выдох)','[га] — будинок (легкий видих)',null,'Das Haus ist groß.','Дом большой.','Будинок великий.',null,null,array[]::text[],1007),
('a1-abc-i','A1',null,'a1-start-alphabet','letter','I i — der Igel','[и] — ёж','[і] — їжак',null,'Im Garten ist ein Igel.','В саду ёж.','У саду їжак.',null,null,array[]::text[],1008),
('a1-abc-j','A1',null,'a1-start-alphabet','letter','J j — ja','[йот] — да','[йот] — так',null,'Ja, das stimmt.','Да, верно.','Так, правильно.',null,null,array[]::text[],1009),
('a1-abc-k','A1',null,'a1-start-alphabet','letter','K k — das Kind','[ка] — ребёнок','[ка] — дитина',null,'Das Kind spielt.','Ребёнок играет.','Дитина грається.',null,null,array[]::text[],1010),
('a1-abc-l','A1',null,'a1-start-alphabet','letter','L l — lernen','[эль] — учить','[ель] — вчити',null,'Ich lerne jeden Tag.','Я учусь каждый день.','Я вчуся щодня.',null,null,array[]::text[],1011),
('a1-abc-m','A1',null,'a1-start-alphabet','letter','M m — die Milch','[эм] — молоко','[ем] — молоко',null,'Die Milch ist im Kühlschrank.','Молоко в холодильнике.','Молоко в холодильнику.',null,null,array[]::text[],1012),
('a1-abc-n','A1',null,'a1-start-alphabet','letter','N n — der Name','[эн] — имя','[ен] — ім''я',null,'Wie ist Ihr Name?','Как вас зовут?','Як вас звати?',null,null,array[]::text[],1013),
('a1-abc-o','A1',null,'a1-start-alphabet','letter','O o — das Obst','[о] — фрукты','[о] — фрукти',null,'Obst ist gesund.','Фрукты полезны.','Фрукти корисні.',null,null,array[]::text[],1014),
('a1-abc-p','A1',null,'a1-start-alphabet','letter','P p — die Post','[пэ] — почта','[пе] — пошта',null,'Die Post ist heute zu.','Почта сегодня закрыта.','Пошта сьогодні зачинена.',null,null,array[]::text[],1015),
('a1-abc-q','A1',null,'a1-start-alphabet','letter','Qu qu — die Quittung','[ку] читается [кв] — квитанция, чек','[ку] читається [кв] — квитанція, чек',null,'Brauchen Sie eine Quittung?','Вам нужен чек?','Вам потрібен чек?',null,null,array[]::text[],1016),
('a1-abc-r','A1',null,'a1-start-alphabet','letter','R r — rot','[эр] — красный (горловое r)','[ер] — червоний (горлове r)',null,'Die Ampel ist rot.','Светофор красный.','Світлофор червоний.',null,null,array['pronunciation']::text[],1017),
('a1-abc-s','A1',null,'a1-start-alphabet','letter','S s — die Sonne','[эс] — солнце (s перед гласной = [з])','[ес] — сонце (s перед голосною = [з])',null,'Die Sonne scheint.','Светит солнце.','Світить сонце.',null,null,array[]::text[],1018),
('a1-abc-t','A1',null,'a1-start-alphabet','letter','T t — der Tee','[тэ] — чай','[те] — чай',null,'Möchtest du Tee?','Хочешь чаю?','Хочеш чаю?',null,null,array[]::text[],1019),
('a1-abc-u','A1',null,'a1-start-alphabet','letter','U u — die Uhr','[у] — часы','[у] — годинник',null,'Die Uhr ist neu.','Часы новые.','Годинник новий.',null,null,array[]::text[],1020),
('a1-abc-v','A1',null,'a1-start-alphabet','letter','V v — der Vater','[фау] — отец (v обычно = [ф])','[фау] — батько (v зазвичай = [ф])',null,'Mein Vater arbeitet viel.','Мой отец много работает.','Мій батько багато працює.',null,null,array[]::text[],1021),
('a1-abc-w','A1',null,'a1-start-alphabet','letter','W w — das Wasser','[вэ] — вода (w = [в])','[ве] — вода (w = [в])',null,'Ein Glas Wasser, bitte.','Стакан воды, пожалуйста.','Склянку води, будь ласка.',null,null,array[]::text[],1022),
('a1-abc-x','A1',null,'a1-start-alphabet','letter','X x — das Taxi','[икс] — такси','[ікс] — таксі',null,'Wir nehmen ein Taxi.','Мы возьмём такси.','Ми візьмемо таксі.',null,null,array[]::text[],1023),
('a1-abc-y','A1',null,'a1-start-alphabet','letter','Y y — das Handy','[ипсилон] — мобильный телефон','[іпсилон] — мобільний телефон',null,'Mein Handy ist leer.','У меня сел телефон.','У мене розрядився телефон.',null,null,array[]::text[],1024),
('a1-abc-z','A1',null,'a1-start-alphabet','letter','Z z — die Zeit','[цэт] — время (z = [ц])','[цет] — час (z = [ц])',null,'Hast du Zeit?','У тебя есть время?','У тебе є час?',null,null,array[]::text[],1025),
('a1-abc-ae','A1',null,'a1-start-alphabet','letter','Ä ä — der Käse','[э] — сыр','[е] — сир',null,'Der Käse ist lecker.','Сыр вкусный.','Сир смачний.',null,null,array['pronunciation','umlaut']::text[],1026),
('a1-abc-oe','A1',null,'a1-start-alphabet','letter','Ö ö — schön','[ё] без «й»: губы как для «о», язык как для «э» — красивый','[ьо] без «й»: губи як для «о», язик як для «е» — гарний',null,'Das Wetter ist schön.','Погода хорошая.','Погода гарна.',null,null,array['pronunciation','umlaut']::text[],1027),
('a1-abc-ue','A1',null,'a1-start-alphabet','letter','Ü ü — müde','[ю] без «й»: губы как для «у», язык как для «и» — уставший','[ю] без «й»: губи як для «у», язик як для «і» — втомлений',null,'Ich bin heute sehr müde.','Я сегодня очень устал(а).','Я сьогодні дуже втомився (втомилася).',null,null,array['pronunciation','umlaut']::text[],1028),
('a1-abc-ss','A1',null,'a1-start-alphabet','letter','ß — die Straße','[эсцэт] = долгое [с] — улица','[есцет] = довге [с] — вулиця',null,'Ich wohne in der Hauptstraße.','Я живу на Хауптштрассе.','Я живу на Гауптштрассе.',null,null,array[]::text[],1029),
('a1-abc-ch1','A1',null,'a1-start-alphabet','letter','ch — ich, nicht','после e, i, ä, ö, ü: мягкое шипящее [хь]','після e, i, ä, ö, ü: м''яке шипляче [хь]',null,'Ich spreche nicht viel.','Я говорю немного.','Я розмовляю небагато.',null,null,array['pronunciation']::text[],1030),
('a1-abc-ch2','A1',null,'a1-start-alphabet','letter','ch — acht, Buch','после a, o, u: твёрдое [х]','після a, o, u: тверде [х]',null,'Das Buch kostet acht Euro.','Книга стоит восемь евро.','Книжка коштує вісім євро.',null,null,array['pronunciation']::text[],1031),
('a1-abc-sch','A1',null,'a1-start-alphabet','letter','sch — die Schule','[ш] — школа','[ш] — школа',null,'Die Schule beginnt um acht.','Школа начинается в восемь.','Школа починається о восьмій.',null,null,array[]::text[],1032),
('a1-abc-st','A1',null,'a1-start-alphabet','letter','st / sp — die Stadt, der Sport','в начале слова [шт] / [шп]','на початку слова [шт] / [шп]',null,'In der Stadt gibt es viel Sport.','В городе много спорта.','У місті багато спорту.',null,null,array[]::text[],1033),
('a1-abc-ei','A1',null,'a1-start-alphabet','letter','ei — drei, klein','[ай]','[ай]',null,'Ich habe drei kleine Kinder.','У меня трое маленьких детей.','У мене троє маленьких дітей.',null,null,array['pronunciation']::text[],1034),
('a1-abc-ie','A1',null,'a1-start-alphabet','letter','ie — die Liebe, vier','долгое [и:]','довге [і:]',null,'Wir sind vier Personen.','Нас четыре человека.','Нас четверо.',null,null,array['pronunciation']::text[],1035),
('a1-abc-eu','A1',null,'a1-start-alphabet','letter','eu / äu — heute, Häuser','[ой]','[ой]',null,'Heute ist es kalt.','Сегодня холодно.','Сьогодні холодно.',null,null,array['pronunciation']::text[],1036),
('a1-abc-er','A1',null,'a1-start-alphabet','letter','-er — der Lehrer, die Mutter','на конце слова почти [а]: «лера», «мута»','у кінці слова майже [а]: «лера», «мута»',null,'Meine Mutter ist Lehrerin.','Моя мама — учительница.','Моя мама — вчителька.',null,null,array['pronunciation']::text[],1037)
