('a1-num-21','A1',null,'a1-start-numbers','number','einundzwanzig','21 — сначала единицы, потом десятки: «один-и-двадцать»','21 — спочатку одиниці, потім десятки: «один-і-двадцять»',null,'Ich wohne in der Nummer einundzwanzig.','Я живу в доме номер 21.','Я живу в будинку номер 21.',null,null,array[]::text[],2004),
('a1-num-phone','A1',null,'a1-start-numbers','number','Meine Nummer ist null eins sieben sechs …','Номер телефона диктуют по одной цифре.','Номер телефону диктують по одній цифрі.',null,null,null,null,null,null,array[]::text[],2005),
('a1-num-price','A1',null,'a1-start-numbers','number','Das kostet drei Euro neunzig.','Это стоит 3,90 €.','Це коштує 3,90 €.','Das ___ drei Euro neunzig.',null,null,null,null,null,array[]::text[],2006),
('a1-num-age','A1',null,'a1-start-numbers','number','Meine Tochter ist sieben.','Моей дочери семь.','Моїй доньці сім.',null,null,null,null,null,null,array[]::text[],2007),
('a1-time-uhr','A1',null,'a1-start-numbers','phrase','Es ist acht Uhr.','Сейчас восемь часов.','Зараз восьма година.',null,null,null,null,null,null,array[]::text[],2008),
('a1-time-viertelnach','A1',null,'a1-start-numbers','phrase','Es ist Viertel nach zehn.','Четверть одиннадцатого (10:15).','Чверть на одинадцяту (10:15).',null,null,null,null,null,null,array[]::text[],2009),
('a1-time-viertelvor','A1',null,'a1-start-numbers','phrase','Es ist Viertel vor zwölf.','Без четверти двенадцать (11:45).','За чверть дванадцята (11:45).',null,null,null,null,null,null,array[]::text[],2010),
('a1-time-halb','A1',null,'a1-start-numbers','phrase','Es ist halb sieben.','Половина седьмого (6:30) — «halb» смотрит на следующий час!','Пів на сьому (6:30) — «halb» дивиться на наступну годину!',null,null,null,null,null,null,array['typical_error']::text[],2011),
('a1-time-official','A1',null,'a1-start-numbers','phrase','Der Termin ist um 14:30 Uhr.','Приём в 14:30 (официально — 24-часовой формат: vierzehn Uhr dreißig).','Прийом о 14:30 (офіційно — 24-годинний формат: vierzehn Uhr dreißig).',null,null,null,null,null,null,array[]::text[],2012),
('a1-time-um','A1',null,'a1-start-numbers','phrase','Um wie viel Uhr?','Во сколько?','О котрій?',null,null,null,null,null,null,array[]::text[],2013),
('a1-time-von-bis','A1',null,'a1-start-numbers','phrase','Die Praxis ist von acht bis zwölf geöffnet.','Кабинет врача открыт с восьми до двенадцати.','Кабінет лікаря відкритий з восьмої до дванадцятої.',null,null,null,null,null,null,array[]::text[],2014),
('a1-day-montag','A1',null,'a1-start-numbers','phrase','am Montag, am Dienstag, am Mittwoch','в понедельник, во вторник, в среду (дни — с «am»)','у понеділок, у вівторок, у середу (дні — з «am»)',null,null,null,null,null,null,array[]::text[],2015),
('a1-day-donnerstag','A1',null,'a1-start-numbers','phrase','am Donnerstag, am Freitag, am Samstag, am Sonntag','в четверг, в пятницу, в субботу, в воскресенье','у четвер, у п''ятницю, у суботу, у неділю',null,null,null,null,null,null,array[]::text[],2016),
('a1-day-wochenende','A1',null,'a1-start-numbers','phrase','am Wochenende','на выходных','на вихідних',null,null,null,null,null,null,array[]::text[],2017),
('a1-time-morgen','A1',null,'a1-start-numbers','phrase','heute, morgen, übermorgen, gestern','сегодня, завтра, послезавтра, вчера','сьогодні, завтра, післязавтра, вчора',null,null,null,null,null,null,array[]::text[],2018),
('a1-time-tageszeit','A1',null,'a1-start-numbers','phrase','am Morgen, am Mittag, am Nachmittag, am Abend, in der Nacht','утром, в обед, после обеда, вечером, ночью','вранці, в обід, після обіду, ввечері, вночі',null,null,null,null,null,null,array[]::text[],2019),
('a1-month-im','A1',null,'a1-start-numbers','phrase','im Januar, im Mai, im Dezember','в январе, в мае, в декабре (месяцы — с «im»)','у січні, у травні, у грудні (місяці — з «im»)',null,null,null,null,null,null,array[]::text[],2020),
('a1-date','A1',null,'a1-start-numbers','phrase','Heute ist der dritte Oktober.','Сегодня третье октября.','Сьогодні третє жовтня.',null,null,null,null,null,null,array[]::text[],2021),
('a1-date-birthday','A1',null,'a1-start-numbers','phrase','Ich habe am zwölften März Geburtstag.','У меня день рождения двенадцатого марта.','У мене день народження дванадцятого березня.','Ich habe am zwölften März ___.',null,null,null,null,null,array[]::text[],2022),
('a1-time-dauer','A1',null,'a1-start-numbers','phrase','Das dauert zehn Minuten.','Это займёт десять минут.','Це триватиме десять хвилин.',null,null,null,null,null,null,array[]::text[],2023)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-kennenlernen-1','A1','kennenlernen','vocab','Знакомство','Знайомство',10) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-ken-01','A1','kennenlernen','a1-kennenlernen-1','phrase','Darf ich mich vorstellen? Ich bin Olga.','Разрешите представиться? Я Ольга.','Дозвольте представитися? Я Ольга.',null,null,null,null,null,null,array[]::text[],10000),
('a1-ken-02','A1','kennenlernen','a1-kennenlernen-1','phrase','Mein Vorname ist Taras, mein Nachname ist Kowal.','Моё имя Тарас, моя фамилия Коваль.','Моє ім''я Тарас, моє прізвище Коваль.','Mein ___ ist Taras, mein Nachname ist Kowal.',null,null,null,null,null,array[]::text[],10001),
('a1-ken-03','A1','kennenlernen','a1-kennenlernen-1','phrase','Ich bin seit einem Jahr in Deutschland.','Я в Германии уже год.','Я в Німеччині вже рік.','Ich bin ___ einem Jahr in Deutschland.',null,null,null,null,null,array['case_dativ']::text[],10002),
('a1-ken-04','A1','kennenlernen','a1-kennenlernen-1','phrase','Meine Muttersprache ist Russisch.','Мой родной язык — русский.','Моя рідна мова — російська.',null,null,null,null,null,null,array[]::text[],10003),
('a1-ken-05','A1','kennenlernen','a1-kennenlernen-1','phrase','Ich spreche Ukrainisch, Russisch und ein bisschen Deutsch.','Я говорю по-украински, по-русски и немного по-немецки.','Я розмовляю українською, російською і трохи німецькою.',null,null,null,null,null,null,array[]::text[],10004),
('a1-ken-06','A1','kennenlernen','a1-kennenlernen-1','phrase','Was machst du beruflich?','Кем ты работаешь?','Ким ти працюєш?',null,null,null,null,null,null,array[]::text[],10005),
('a1-ken-07','A1','kennenlernen','a1-kennenlernen-1','phrase','Ich bin Ingenieur von Beruf.','По профессии я инженер.','За професією я інженер.',null,null,null,null,null,null,array['no_article_profession']::text[],10006),
('a1-ken-08','A1','kennenlernen','a1-kennenlernen-1','phrase','Wo wohnst du genau?','Где именно ты живёшь?','Де саме ти живеш?',null,null,null,null,null,null,array[]::text[],10007),
('a1-ken-09','A1','kennenlernen','a1-kennenlernen-1','phrase','Das ist mein Mann, und das ist meine Tochter.','Это мой муж, а это моя дочь.','Це мій чоловік, а це моя донька.',null,null,null,null,null,null,array[]::text[],10008),
('a1-ken-10','A1','kennenlernen','a1-kennenlernen-1','phrase','Was sind deine Hobbys?','Какие у тебя хобби?','Які в тебе хобі?',null,null,null,null,null,null,array[]::text[],10009),
('a1-ken-11','A1','kennenlernen','a1-kennenlernen-1','word','der Name','имя','ім''я',null,'Können Sie Ihren Namen buchstabieren?','Можете продиктовать свою фамилию по буквам?','Можете продиктувати своє прізвище по літерах?','der','die Namen',array[]::text[],10010),
('a1-ken-12','A1','kennenlernen','a1-kennenlernen-1','word','das Land','страна','країна',null,'Aus welchem Land kommen Sie?','Из какой вы страны?','З якої ви країни?','das','die Länder',array[]::text[],10011),
('a1-ken-13','A1','kennenlernen','a1-kennenlernen-1','word','die Sprache','язык','мова',null,'Welche Sprachen sprichst du?','На каких языках ты говоришь?','Якими мовами ти розмовляєш?','die','die Sprachen',array[]::text[],10012),
('a1-ken-14','A1','kennenlernen','a1-kennenlernen-1','word','der Beruf','профессия','професія',null,'Was ist Ihr Beruf?','Какая у вас профессия?','Яка у вас професія?','der','die Berufe',array[]::text[],10013),
('a1-ken-15','A1','kennenlernen','a1-kennenlernen-1','word','die Adresse','адрес','адреса',null,'Meine Adresse ist Gartenstraße 5.','Мой адрес — Гартенштрассе, 5.','Моя адреса — Гартенштрассе, 5.','die','die Adressen',array[]::text[],10014)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-familie-1','A1','familie','vocab','Семья','Сім''я',11) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-fam-01','A1','familie','a1-familie-1','phrase','Hast du Geschwister?','У тебя есть братья или сёстры?','У тебе є брати чи сестри?',null,null,null,null,null,null,array[]::text[],11000),
('a1-fam-02','A1','familie','a1-familie-1','phrase','Ich habe einen Bruder und eine Schwester.','У меня есть брат и сестра.','У мене є брат і сестра.','Ich habe ___ Bruder und eine Schwester.',null,null,null,null,null,array['case_akkusativ']::text[],11001),
('a1-fam-03','A1','familie','a1-familie-1','phrase','Meine Eltern leben noch in der Ukraine.','Мои родители ещё живут в Украине.','Мої батьки ще живуть в Україні.',null,null,null,null,null,null,array[]::text[],11002),
('a1-fam-04','A1','familie','a1-familie-1','phrase','Mein Sohn geht in die Kita.','Мой сын ходит в детский сад.','Мій син ходить у дитячий садок.','Mein Sohn geht in ___ Kita.',null,null,null,null,null,array['case_akkusativ']::text[],11003),
('a1-fam-05','A1','familie','a1-familie-1','phrase','Wir sind zu viert.','Нас четверо.','Нас четверо.',null,null,null,null,null,null,array[]::text[],11004),
('a1-fam-06','A1','familie','a1-familie-1','phrase','Ich bin geschieden.','Я в разводе.','Я розлучений (розлучена).',null,null,null,null,null,null,array[]::text[],11005),
('a1-fam-07','A1','familie','a1-familie-1','phrase','Meine Frau arbeitet in einem Supermarkt.','Моя жена работает в супермаркете.','Моя дружина працює в супермаркеті.',null,null,null,null,null,null,array['case_dativ']::text[],11006),
('a1-fam-08','A1','familie','a1-familie-1','phrase','Wie alt sind deine Kinder?','Сколько лет твоим детям?','Скільки років твоїм дітям?',null,null,null,null,null,null,array[]::text[],11007),
('a1-fam-09','A1','familie','a1-familie-1','phrase','Am Wochenende besuchen wir meine Oma.','На выходных мы навещаем мою бабушку.','На вихідних ми відвідуємо мою бабусю.','Am Wochenende ___ wir meine Oma.',null,null,null,null,null,array['word_order_v2']::text[],11008),
('a1-fam-10','A1','familie','a1-familie-1','word','die Mutter','мать','мати',null,'Meine Mutter kocht sehr gut.','Моя мама очень хорошо готовит.','Моя мама дуже добре готує.','die','die Mütter',array[]::text[],11009),
('a1-fam-11','A1','familie','a1-familie-1','word','der Vater','отец','батько',null,'Mein Vater ist Rentner.','Мой отец — пенсионер.','Мій батько — пенсіонер.','der','die Väter',array[]::text[],11010),
('a1-fam-12','A1','familie','a1-familie-1','word','das Kind','ребёнок','дитина',null,'Das Kind schläft schon.','Ребёнок уже спит.','Дитина вже спить.','das','die Kinder',array[]::text[],11011),
('a1-fam-13','A1','familie','a1-familie-1','word','die Tochter','дочь','донька',null,'Meine Tochter ist zehn Jahre alt.','Моей дочери десять лет.','Моїй доньці десять років.','die','die Töchter',array[]::text[],11012),
('a1-fam-14','A1','familie','a1-familie-1','word','der Sohn','сын','син',null,'Unser Sohn spielt Fußball.','Наш сын играет в футбол.','Наш син грає у футбол.','der','die Söhne',array[]::text[],11013),
('a1-fam-15','A1','familie','a1-familie-1','word','die Eltern','родители (только мн. ч.)','батьки (лише мн.)',null,'Meine Eltern rufen jeden Sonntag an.','Мои родители звонят каждое воскресенье.','Мої батьки телефонують щонеділі.',null,'die Eltern',array[]::text[],11014),
('a1-fam-16','A1','familie','a1-familie-1','word','das Baby','младенец','немовля',null,'Das Baby weint.','Малыш плачет.','Немовля плаче.','das','die Babys',array[]::text[],11015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-wohnen-1','A1','wohnen','vocab','Жильё','Житло',12) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-woh-01','A1','wohnen','a1-wohnen-1','phrase','Die Wohnung hat drei Zimmer, Küche und Bad.','В квартире три комнаты, кухня и ванная.','У квартирі три кімнати, кухня й ванна.',null,null,null,null,null,null,array[]::text[],12000),
('a1-woh-02','A1','wohnen','a1-wohnen-1','phrase','Wie hoch ist die Miete?','Какая арендная плата?','Яка орендна плата?',null,null,null,null,null,null,array[]::text[],12001),
('a1-woh-03','A1','wohnen','a1-wohnen-1','phrase','Die Miete ist 700 Euro warm.','Аренда — 700 евро с коммунальными.','Оренда — 700 євро з комунальними.',null,null,null,null,null,null,array[]::text[],12002),
('a1-woh-04','A1','wohnen','a1-wohnen-1','phrase','Ist die Wohnung noch frei?','Квартира ещё свободна?','Квартира ще вільна?',null,null,null,null,null,null,array[]::text[],12003),
('a1-woh-05','A1','wohnen','a1-wohnen-1','phrase','Wann kann ich die Wohnung besichtigen?','Когда можно посмотреть квартиру?','Коли можна подивитися квартиру?',null,null,null,null,null,null,array['verb_final']::text[],12004),
('a1-woh-06','A1','wohnen','a1-wohnen-1','phrase','Wir wohnen im dritten Stock.','Мы живём на третьем этаже.','Ми живемо на третьому поверсі.',null,null,null,null,null,null,array[]::text[],12005),
('a1-woh-07','A1','wohnen','a1-wohnen-1','phrase','Gibt es einen Aufzug?','Есть лифт?','Є ліфт?','Gibt es ___ Aufzug?',null,null,null,null,null,array[]::text[],12006),
('a1-woh-08','A1','wohnen','a1-wohnen-1','phrase','Das Fenster in der Küche geht nicht zu.','Окно на кухне не закрывается.','Вікно на кухні не зачиняється.',null,null,null,null,null,null,array[]::text[],12007),
('a1-woh-09','A1','wohnen','a1-wohnen-1','phrase','Der Müll kommt in die gelbe Tonne.','Этот мусор — в жёлтый бак.','Це сміття — у жовтий бак.',null,null,null,null,null,null,array['case_akkusativ']::text[],12008),
('a1-woh-10','A1','wohnen','a1-wohnen-1','phrase','Ab 22 Uhr ist Ruhezeit.','С 22 часов — время тишины.','З 22 години — час тиші.',null,null,null,null,null,null,array[]::text[],12009),
('a1-woh-11','A1','wohnen','a1-wohnen-1','word','die Wohnung','квартира','квартира',null,'Unsere Wohnung ist klein, aber hell.','Наша квартира маленькая, но светлая.','Наша квартира маленька, але світла.','die','die Wohnungen',array[]::text[],12010),
('a1-woh-12','A1','wohnen','a1-wohnen-1','word','das Zimmer','комната','кімната',null,'Das Zimmer hat einen Balkon.','В комнате есть балкон.','У кімнаті є балкон.','das','die Zimmer',array[]::text[],12011),
('a1-woh-13','A1','wohnen','a1-wohnen-1','word','die Küche','кухня','кухня',null,'Die Küche ist neu.','Кухня новая.','Кухня нова.','die','die Küchen',array[]::text[],12012),
('a1-woh-14','A1','wohnen','a1-wohnen-1','word','der Vermieter','арендодатель','орендодавець',null,'Ich rufe den Vermieter an.','Я позвоню арендодателю.','Я зателефоную орендодавцю.','der','die Vermieter',array[]::text[],12013),
('a1-woh-15','A1','wohnen','a1-wohnen-1','word','der Schlüssel','ключ','ключ',null,'Ich finde meinen Schlüssel nicht.','Я не могу найти свой ключ.','Я не можу знайти свій ключ.','der','die Schlüssel',array[]::text[],12014),
('a1-woh-16','A1','wohnen','a1-wohnen-1','word','das Bad','ванная','ванна кімната',null,'Das Bad ist gleich links.','Ванная сразу слева.','Ванна одразу ліворуч.','das','die Bäder',array[]::text[],12015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-arbeit-1','A1','arbeit','vocab','Работа','Робота',13) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-arb-01','A1','arbeit','a1-arbeit-1','phrase','Ich arbeite Vollzeit.','Я работаю полный день.','Я працюю повний день.',null,null,null,null,null,null,array[]::text[],13000),
('a1-arb-02','A1','arbeit','a1-arbeit-1','phrase','Ich arbeite in Teilzeit, zwanzig Stunden pro Woche.','Я работаю неполный день, двадцать часов в неделю.','Я працюю неповний день, двадцять годин на тиждень.',null,null,null,null,null,null,array[]::text[],13001),
('a1-arb-03','A1','arbeit','a1-arbeit-1','phrase','Ich fange um sieben Uhr an.','Я начинаю в семь часов.','Я починаю о сьомій.','Ich fange um sieben Uhr ___.',null,null,null,null,null,array['separable_verb']::text[],13002),
('a1-arb-04','A1','arbeit','a1-arbeit-1','phrase','Morgen habe ich frei.','Завтра у меня выходной.','Завтра в мене вихідний.',null,null,null,null,null,null,array['word_order_v2']::text[],13003),
('a1-arb-05','A1','arbeit','a1-arbeit-1','phrase','Ich bin heute krank und kann nicht kommen.','Я сегодня заболел(а) и не могу прийти.','Я сьогодні захворів (захворіла) і не можу прийти.',null,null,null,null,null,null,array['verb_final']::text[],13004),
('a1-arb-06','A1','arbeit','a1-arbeit-1','phrase','Mein Chef ist sehr nett.','Мой начальник очень приятный.','Мій начальник дуже приємний.',null,null,null,null,null,null,array[]::text[],13005),
('a1-arb-07','A1','arbeit','a1-arbeit-1','phrase','Ich mache gerade einen Deutschkurs.','Я сейчас прохожу курс немецкого.','Я зараз проходжу курс німецької.',null,null,null,null,null,null,array[]::text[],13006),
('a1-arb-08','A1','arbeit','a1-arbeit-1','phrase','Ich habe eine Bewerbung geschrieben.','Я написал(а) заявление о приёме на работу.','Я написав (написала) заяву про прийом на роботу.',null,null,null,null,null,null,array['perfekt']::text[],13007),
('a1-arb-09','A1','arbeit','a1-arbeit-1','phrase','Wann ist Mittagspause?','Когда обеденный перерыв?','Коли обідня перерва?',null,null,null,null,null,null,array[]::text[],13008),
('a1-arb-10','A1','arbeit','a1-arbeit-1','word','die Arbeit','работа','робота',null,'Nach der Arbeit gehe ich einkaufen.','После работы я иду за покупками.','Після роботи я йду по покупки.','die','die Arbeiten',array[]::text[],13009),
('a1-arb-11','A1','arbeit','a1-arbeit-1','word','der Kollege','коллега (м.)','колега (ч.)',null,'Mein Kollege hilft mir.','Мой коллега мне помогает.','Мій колега мені допомагає.','der','die Kollegen',array[]::text[],13010),
('a1-arb-12','A1','arbeit','a1-arbeit-1','word','die Kollegin','коллега (ж.)','колега (ж.)',null,'Meine Kollegin kommt aus Polen.','Моя коллега из Польши.','Моя колега з Польщі.','die','die Kolleginnen',array[]::text[],13011),
('a1-arb-13','A1','arbeit','a1-arbeit-1','word','der Lohn','зарплата','зарплата',null,'Der Lohn kommt am Monatsende.','Зарплата приходит в конце месяца.','Зарплата приходить наприкінці місяця.','der','die Löhne',array[]::text[],13012),
('a1-arb-14','A1','arbeit','a1-arbeit-1','word','die Firma','фирма','фірма',null,'Die Firma sucht neue Mitarbeiter.','Фирма ищет новых сотрудников.','Фірма шукає нових працівників.','die','die Firmen',array[]::text[],13013),
('a1-arb-15','A1','arbeit','a1-arbeit-1','word','der Urlaub','отпуск','відпустка',null,'Im August habe ich Urlaub.','В августе у меня отпуск.','У серпні в мене відпустка.','der','die Urlaube',array[]::text[],13014)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-gesundheit-1','A1','gesundheit','vocab','Врач и здоровье','Лікар і здоров''я',14) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-ges-01','A1','gesundheit','a1-gesundheit-1','phrase','Ich möchte einen Termin beim Hausarzt.','Я хочу записаться к семейному врачу.','Я хочу записатися до сімейного лікаря.',null,null,null,null,null,null,array['case_dativ']::text[],14000),
('a1-ges-02','A1','gesundheit','a1-gesundheit-1','phrase','Haben Sie heute noch einen Termin frei?','У вас есть ещё свободное время на сегодня?','У вас є ще вільний час на сьогодні?',null,null,null,null,null,null,array[]::text[],14001),
('a1-ges-03','A1','gesundheit','a1-gesundheit-1','phrase','Was fehlt Ihnen?','Что вас беспокоит?','Що вас турбує?',null,null,null,null,null,null,array[]::text[],14002),
('a1-ges-04','A1','gesundheit','a1-gesundheit-1','phrase','Mein Bauch tut weh.','У меня болит живот.','У мене болить живіт.','Mein Bauch tut ___.',null,null,null,null,null,array[]::text[],14003),
('a1-ges-05','A1','gesundheit','a1-gesundheit-1','phrase','Ich habe seit drei Tagen Fieber.','У меня три дня температура.','У мене три дні температура.',null,null,null,null,null,null,array['case_dativ']::text[],14004),
('a1-ges-06','A1','gesundheit','a1-gesundheit-1','phrase','Ich habe Husten und Schnupfen.','У меня кашель и насморк.','У мене кашель і нежить.',null,null,null,null,null,null,array[]::text[],14005),
('a1-ges-07','A1','gesundheit','a1-gesundheit-1','phrase','Hier ist meine Versichertenkarte.','Вот моя медицинская страховая карта.','Ось моя медична страхова картка.',null,null,null,null,null,null,array[]::text[],14006),
('a1-ges-08','A1','gesundheit','a1-gesundheit-1','phrase','Nehmen Sie die Tabletten dreimal am Tag.','Принимайте таблетки три раза в день.','Приймайте таблетки тричі на день.',null,null,null,null,null,null,array[]::text[],14007),
('a1-ges-09','A1','gesundheit','a1-gesundheit-1','phrase','Ich brauche eine Krankmeldung für die Arbeit.','Мне нужен больничный для работы.','Мені потрібен лікарняний для роботи.',null,null,null,null,null,null,array[]::text[],14008),
('a1-ges-10','A1','gesundheit','a1-gesundheit-1','phrase','Gute Besserung!','Выздоравливай(те)!','Одужуй(те)!',null,null,null,null,null,null,array[]::text[],14009),
('a1-ges-11','A1','gesundheit','a1-gesundheit-1','word','der Arzt','врач (м.)','лікар',null,'Ich gehe morgen zum Arzt.','Завтра я иду к врачу.','Завтра я йду до лікаря.','der','die Ärzte',array['case_dativ']::text[],14010),
('a1-ges-12','A1','gesundheit','a1-gesundheit-1','word','die Ärztin','врач (ж.)','лікарка',null,'Die Ärztin ist sehr freundlich.','Врач очень приветливая.','Лікарка дуже привітна.','die','die Ärztinnen',array[]::text[],14011),
('a1-ges-13','A1','gesundheit','a1-gesundheit-1','word','die Praxis','кабинет врача, практика','кабінет лікаря, практика',null,'Die Praxis ist mittwochs nachmittags geschlossen.','По средам после обеда кабинет закрыт.','У середу після обіду кабінет зачинений.','die','die Praxen',array[]::text[],14012),
('a1-ges-14','A1','gesundheit','a1-gesundheit-1','word','das Rezept','рецепт','рецепт',null,'Mit dem Rezept gehen Sie in die Apotheke.','С рецептом идите в аптеку.','З рецептом ідіть в аптеку.','das','die Rezepte',array[]::text[],14013),
('a1-ges-15','A1','gesundheit','a1-gesundheit-1','word','die Apotheke','аптека','аптека',null,'Wo ist die nächste Apotheke?','Где ближайшая аптека?','Де найближча аптека?','die','die Apotheken',array[]::text[],14014),
('a1-ges-16','A1','gesundheit','a1-gesundheit-1','word','der Kopf','голова','голова',null,'Mir tut der Kopf weh.','У меня болит голова.','У мене болить голова.','der','die Köpfe',array[]::text[],14015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-einkaufen-1','A1','einkaufen','vocab','Покупки','Покупки',15) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-ein-01','A1','einkaufen','a1-einkaufen-1','phrase','Ich suche Milch. Wo finde ich die?','Я ищу молоко. Где его найти?','Я шукаю молоко. Де його знайти?',null,null,null,null,null,null,array[]::text[],15000),
('a1-ein-02','A1','einkaufen','a1-einkaufen-1','phrase','Haben Sie das auch in Größe 40?','У вас это есть 40-го размера?','У вас це є 40-го розміру?',null,null,null,null,null,null,array[]::text[],15001),
('a1-ein-03','A1','einkaufen','a1-einkaufen-1','phrase','Kann ich das anprobieren?','Можно это примерить?','Можна це приміряти?',null,null,null,null,null,null,array['separable_verb']::text[],15002),
('a1-ein-04','A1','einkaufen','a1-einkaufen-1','phrase','Ich möchte das umtauschen.','Я хочу это обменять.','Я хочу це обміняти.',null,null,null,null,null,null,array[]::text[],15003),
('a1-ein-05','A1','einkaufen','a1-einkaufen-1','phrase','Was darf es sein?','Что желаете? (продавец)','Що бажаєте? (продавець)',null,null,null,null,null,null,array[]::text[],15004),
('a1-ein-06','A1','einkaufen','a1-einkaufen-1','phrase','Ich hätte gern 200 Gramm Käse.','Мне, пожалуйста, 200 грамм сыра.','Мені, будь ласка, 200 грамів сиру.',null,null,null,null,null,null,array[]::text[],15005),
('a1-ein-07','A1','einkaufen','a1-einkaufen-1','phrase','Sonst noch etwas?','Что-нибудь ещё?','Щось іще?',null,null,null,null,null,null,array[]::text[],15006),
('a1-ein-08','A1','einkaufen','a1-einkaufen-1','phrase','Nein, das ist alles.','Нет, это всё.','Ні, це все.',null,null,null,null,null,null,array[]::text[],15007),
('a1-ein-09','A1','einkaufen','a1-einkaufen-1','phrase','Das Angebot gilt bis Samstag.','Акция действует до субботы.','Акція діє до суботи.',null,null,null,null,null,null,array[]::text[],15008),
('a1-ein-10','A1','einkaufen','a1-einkaufen-1','phrase','Der Supermarkt hat bis 22 Uhr auf.','Супермаркет открыт до 22 часов.','Супермаркет відчинений до 22 години.',null,null,null,null,null,null,array[]::text[],15009),
('a1-ein-11','A1','einkaufen','a1-einkaufen-1','word','das Brot','хлеб','хліб',null,'Ein Vollkornbrot, bitte.','Цельнозерновой хлеб, пожалуйста.','Цільнозерновий хліб, будь ласка.','das','die Brote',array[]::text[],15010),
('a1-ein-12','A1','einkaufen','a1-einkaufen-1','word','die Kasse','касса','каса',null,'Bitte zahlen Sie an der Kasse.','Пожалуйста, оплатите на кассе.','Будь ласка, оплатіть на касі.','die','die Kassen',array[]::text[],15011),
('a1-ein-13','A1','einkaufen','a1-einkaufen-1','word','der Preis','цена','ціна',null,'Der Preis ist gut.','Цена хорошая.','Ціна хороша.','der','die Preise',array[]::text[],15012),
('a1-ein-14','A1','einkaufen','a1-einkaufen-1','word','das Geld','деньги (ед. ч.!)','гроші (одн.!)',null,'Ich habe kein Geld dabei.','У меня нет с собой денег.','У мене немає з собою грошей.','das',null,array['typical_error']::text[],15013),
('a1-ein-15','A1','einkaufen','a1-einkaufen-1','word','die Tüte','пакет','пакет',null,'Die Tüte kostet zehn Cent.','Пакет стоит десять центов.','Пакет коштує десять центів.','die','die Tüten',array[]::text[],15014),
('a1-ein-16','A1','einkaufen','a1-einkaufen-1','word','der Kassenbon','кассовый чек','касовий чек',null,'Brauchen Sie den Kassenbon?','Вам нужен чек?','Вам потрібен чек?','der','die Kassenbons',array[]::text[],15015)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-aemter-1','A1','aemter','vocab','Ведомства','Установи',16) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-amt-01','A1','aemter','a1-aemter-1','phrase','Ich möchte mich anmelden.','Я хочу зарегистрироваться (по месту жительства).','Я хочу зареєструватися (за місцем проживання).',null,null,null,null,null,null,array['reflexive']::text[],16000),
('a1-amt-02','A1','aemter','a1-aemter-1','phrase','Welche Unterlagen brauche ich?','Какие документы мне нужны?','Які документи мені потрібні?',null,null,null,null,null,null,array[]::text[],16001),
('a1-amt-03','A1','aemter','a1-aemter-1','phrase','Bitte füllen Sie dieses Formular aus.','Пожалуйста, заполните этот бланк.','Будь ласка, заповніть цей бланк.',null,null,null,null,null,null,array['separable_verb']::text[],16002),
('a1-amt-04','A1','aemter','a1-aemter-1','phrase','Wo muss ich unterschreiben?','Где мне нужно подписать?','Де мені треба підписати?',null,null,null,null,null,null,array[]::text[],16003),
('a1-amt-05','A1','aemter','a1-aemter-1','phrase','Ziehen Sie bitte eine Nummer.','Возьмите, пожалуйста, номерок.','Візьміть, будь ласка, номерок.',null,null,null,null,null,null,array[]::text[],16004),
('a1-amt-06','A1','aemter','a1-aemter-1','phrase','Ich habe einen Brief vom Jobcenter bekommen.','Я получил(а) письмо из джобцентра.','Я отримав (отримала) лист від джобцентру.',null,null,null,null,null,null,array['perfekt']::text[],16005),
('a1-amt-07','A1','aemter','a1-aemter-1','phrase','Ich verstehe diesen Brief nicht.','Я не понимаю это письмо.','Я не розумію цей лист.',null,null,null,null,null,null,array[]::text[],16006),
('a1-amt-08','A1','aemter','a1-aemter-1','phrase','Bis wann muss ich das abgeben?','До какого числа это нужно сдать?','До якого числа це треба здати?',null,null,null,null,null,null,array[]::text[],16007),
('a1-amt-09','A1','aemter','a1-aemter-1','phrase','Mein Aufenthaltstitel läuft bald ab.','Мой вид на жительство скоро заканчивается.','Мій дозвіл на проживання скоро закінчується.',null,null,null,null,null,null,array[]::text[],16008),
('a1-amt-10','A1','aemter','a1-aemter-1','word','das Formular','бланк, анкета','бланк, анкета',null,'Das Formular gibt es auch online.','Бланк есть и онлайн.','Бланк є й онлайн.','das','die Formulare',array[]::text[],16009),
('a1-amt-11','A1','aemter','a1-aemter-1','word','der Ausweis','удостоверение личности','посвідчення особи',null,'Haben Sie Ihren Ausweis dabei?','У вас с собой удостоверение?','У вас із собою посвідчення?','der','die Ausweise',array[]::text[],16010),
('a1-amt-12','A1','aemter','a1-aemter-1','word','der Reisepass','загранпаспорт','закордонний паспорт',null,'Ich brauche eine Kopie von Ihrem Reisepass.','Мне нужна копия вашего паспорта.','Мені потрібна копія вашого паспорта.','der','die Reisepässe',array[]::text[],16011),
('a1-amt-13','A1','aemter','a1-aemter-1','word','die Unterschrift','подпись','підпис',null,'Hier fehlt noch Ihre Unterschrift.','Здесь не хватает вашей подписи.','Тут бракує вашого підпису.','die','die Unterschriften',array[]::text[],16012),
('a1-amt-14','A1','aemter','a1-aemter-1','word','das Amt','ведомство, учреждение','установа, відомство',null,'Das Amt öffnet um halb acht.','Учреждение открывается в половине восьмого.','Установа відкривається о пів на восьму.','das','die Ämter',array[]::text[],16013),
('a1-amt-15','A1','aemter','a1-aemter-1','word','der Termin','запись, назначенная встреча','запис, призначена зустріч',null,'Ohne Termin geht es leider nicht.','Без записи, к сожалению, нельзя.','Без запису, на жаль, не можна.','der','die Termine',array[]::text[],16014)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-verkehr-1','A1','verkehr','vocab','Транспорт','Транспорт',17) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-ver-01','A1','verkehr','a1-verkehr-1','phrase','Ich fahre mit dem Bus zur Arbeit.','Я езжу на работу на автобусе.','Я їжджу на роботу автобусом.','Ich fahre mit ___ Bus zur Arbeit.',null,null,null,null,null,array['case_dativ']::text[],17000),
('a1-ver-02','A1','verkehr','a1-verkehr-1','phrase','Die U-Bahn kommt alle zehn Minuten.','Метро ходит каждые десять минут.','Метро ходить кожні десять хвилин.',null,null,null,null,null,null,array[]::text[],17001),
('a1-ver-03','A1','verkehr','a1-verkehr-1','phrase','Von welchem Gleis fährt der Zug ab?','С какого пути отправляется поезд?','З якої колії відправляється потяг?',null,null,null,null,null,null,array[]::text[],17002),
('a1-ver-04','A1','verkehr','a1-verkehr-1','phrase','Ich muss in Köln umsteigen.','Мне нужно сделать пересадку в Кёльне.','Мені треба пересісти в Кельні.',null,null,null,null,null,null,array['verb_final']::text[],17003),
('a1-ver-05','A1','verkehr','a1-verkehr-1','phrase','Der Bus fällt heute aus.','Автобус сегодня отменён.','Автобус сьогодні скасовано.',null,null,null,null,null,null,array[]::text[],17004),
('a1-ver-06','A1','verkehr','a1-verkehr-1','phrase','Ich habe ein Deutschlandticket.','У меня есть Deutschlandticket (проездной).','У мене є Deutschlandticket (проїзний).',null,null,null,null,null,null,array[]::text[],17005),
('a1-ver-07','A1','verkehr','a1-verkehr-1','phrase','Ich gehe zu Fuß.','Я иду пешком.','Я йду пішки.',null,null,null,null,null,null,array[]::text[],17006),
('a1-ver-08','A1','verkehr','a1-verkehr-1','phrase','An der nächsten Haltestelle steigen wir aus.','На следующей остановке мы выходим.','На наступній зупинці ми виходимо.',null,null,null,null,null,null,array['word_order_v2','separable_verb']::text[],17007),
('a1-ver-09','A1','verkehr','a1-verkehr-1','phrase','Ist der Platz noch frei?','Это место свободно?','Це місце вільне?',null,null,null,null,null,null,array[]::text[],17008),
('a1-ver-10','A1','verkehr','a1-verkehr-1','word','der Bahnhof','вокзал','вокзал',null,'Wir treffen uns am Bahnhof.','Встретимся на вокзале.','Зустрінемося на вокзалі.','der','die Bahnhöfe',array[]::text[],17009),
('a1-ver-11','A1','verkehr','a1-verkehr-1','word','die Haltestelle','остановка','зупинка',null,'Die Haltestelle ist direkt vor dem Haus.','Остановка прямо перед домом.','Зупинка прямо перед будинком.','die','die Haltestellen',array[]::text[],17010),
('a1-ver-12','A1','verkehr','a1-verkehr-1','word','die Fahrkarte','проездной билет','квиток',null,'Die Fahrkarte kaufe ich in der App.','Билет я покупаю в приложении.','Квиток я купую в застосунку.','die','die Fahrkarten',array[]::text[],17011),
('a1-ver-13','A1','verkehr','a1-verkehr-1','word','das Auto','машина','автомобіль',null,'Wir haben kein Auto.','У нас нет машины.','У нас немає автомобіля.','das','die Autos',array[]::text[],17012),
('a1-ver-14','A1','verkehr','a1-verkehr-1','word','das Fahrrad','велосипед','велосипед',null,'Im Sommer fahre ich Fahrrad.','Летом я езжу на велосипеде.','Влітку я їжджу на велосипеді.','das','die Fahrräder',array[]::text[],17013),
('a1-ver-15','A1','verkehr','a1-verkehr-1','word','die Verspätung','опоздание, задержка','запізнення, затримка',null,'Der Zug hat zwanzig Minuten Verspätung.','Поезд опаздывает на двадцать минут.','Потяг запізнюється на двадцять хвилин.','die','die Verspätungen',array[]::text[],17014)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-freizeit-1','A1','freizeit','vocab','Свободное время','Вільний час',18) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-fre-01','A1','freizeit','a1-freizeit-1','phrase','Was machst du am Wochenende?','Что ты делаешь на выходных?','Що ти робиш на вихідних?',null,null,null,null,null,null,array[]::text[],18000),
('a1-fre-02','A1','freizeit','a1-freizeit-1','phrase','Ich gehe gern spazieren.','Я люблю гулять.','Я люблю гуляти.','Ich gehe ___ spazieren.',null,null,null,null,null,array[]::text[],18001),
('a1-fre-03','A1','freizeit','a1-freizeit-1','phrase','Hast du Lust auf Kino?','Хочешь в кино?','Хочеш у кіно?',null,null,null,null,null,null,array[]::text[],18002),
('a1-fre-04','A1','freizeit','a1-freizeit-1','phrase','Ja, gute Idee!','Да, хорошая идея!','Так, гарна ідея!',null,null,null,null,null,null,array[]::text[],18003),
('a1-fre-05','A1','freizeit','a1-freizeit-1','phrase','Heute kann ich leider nicht.','Сегодня, к сожалению, не могу.','Сьогодні, на жаль, не можу.',null,null,null,null,null,null,array['word_order_v2']::text[],18004),
('a1-fre-06','A1','freizeit','a1-freizeit-1','phrase','Wann treffen wir uns?','Когда встретимся?','Коли зустрінемося?',null,null,null,null,null,null,array['reflexive']::text[],18005),
('a1-fre-07','A1','freizeit','a1-freizeit-1','phrase','Treffen wir uns um sechs vor dem Kino?','Встретимся в шесть перед кинотеатром?','Зустрінемося о шостій перед кінотеатром?',null,null,null,null,null,null,array[]::text[],18006),
('a1-fre-08','A1','freizeit','a1-freizeit-1','phrase','Ich spiele Fußball im Verein.','Я играю в футбол в клубе.','Я граю у футбол у клубі.',null,null,null,null,null,null,array[]::text[],18007),
('a1-fre-09','A1','freizeit','a1-freizeit-1','phrase','Am Abend sehe ich fern.','Вечером я смотрю телевизор.','Увечері я дивлюся телевізор.',null,null,null,null,null,null,array['separable_verb','word_order_v2']::text[],18008),
('a1-fre-10','A1','freizeit','a1-freizeit-1','phrase','Ich lese gern Bücher.','Я люблю читать книги.','Я люблю читати книжки.',null,null,null,null,null,null,array[]::text[],18009),
('a1-fre-11','A1','freizeit','a1-freizeit-1','word','das Hobby','хобби','хобі',null,'Mein Hobby ist Kochen.','Моё хобби — готовка.','Моє хобі — кулінарія.','das','die Hobbys',array[]::text[],18010),
('a1-fre-12','A1','freizeit','a1-freizeit-1','word','der Park','парк','парк',null,'Die Kinder spielen im Park.','Дети играют в парке.','Діти граються в парку.','der','die Parks',array[]::text[],18011),
('a1-fre-13','A1','freizeit','a1-freizeit-1','word','das Schwimmbad','бассейн','басейн',null,'Im Sommer gehen wir ins Schwimmbad.','Летом мы ходим в бассейн.','Влітку ми ходимо в басейн.','das','die Schwimmbäder',array[]::text[],18012),
('a1-fre-14','A1','freizeit','a1-freizeit-1','word','der Ausflug','поездка, экскурсия','поїздка, екскурсія',null,'Am Sonntag machen wir einen Ausflug.','В воскресенье мы едем на прогулку за город.','У неділю ми їдемо на прогулянку за місто.','der','die Ausflüge',array[]::text[],18013),
('a1-fre-15','A1','freizeit','a1-freizeit-1','word','die Musik','музыка','музика',null,'Welche Musik hörst du gern?','Какую музыку ты любишь слушать?','Яку музику ти любиш слухати?','die',null,array[]::text[],18014)
insert into public.lessons (id, level_id, topic_id, kind, title_ru, title_uk, sort) values ('a1-schule-1','A1','schule','vocab','Школа и дети','Школа і діти',19) on conflict (id) do update set title_ru = excluded.title_ru, title_uk = excluded.title_uk, sort = excluded.sort, kind = excluded.kind;
insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-sch-01','A1','schule','a1-schule-1','phrase','Mein Sohn geht in die zweite Klasse.','Мой сын ходит во второй класс.','Мій син ходить у другий клас.',null,null,null,null,null,null,array['case_akkusativ']::text[],19000),
('a1-sch-02','A1','schule','a1-schule-1','phrase','Die Schule fängt um acht Uhr an.','Уроки начинаются в восемь.','Уроки починаються о восьмій.',null,null,null,null,null,null,array['separable_verb']::text[],19001),
('a1-sch-03','A1','schule','a1-schule-1','phrase','Ich hole meine Tochter um vier ab.','Я забираю дочь в четыре.','Я забираю доньку о четвертій.','Ich hole meine Tochter um vier ___.',null,null,null,null,null,array['separable_verb']::text[],19002),
('a1-sch-04','A1','schule','a1-schule-1','phrase','Mein Kind ist krank und kommt heute nicht.','Мой ребёнок болен и сегодня не придёт.','Моя дитина хвора й сьогодні не прийде.',null,null,null,null,null,null,array[]::text[],19003),
('a1-sch-05','A1','schule','a1-schule-1','phrase','Wann ist der Elternabend?','Когда родительское собрание?','Коли батьківські збори?',null,null,null,null,null,null,array[]::text[],19004),
('a1-sch-06','A1','schule','a1-schule-1','phrase','Wir suchen einen Kitaplatz.','Мы ищем место в детском саду.','Ми шукаємо місце в дитсадку.',null,null,null,null,null,null,array[]::text[],19005),
('a1-sch-07','A1','schule','a1-schule-1','phrase','Die Kinder machen Hausaufgaben.','Дети делают домашнее задание.','Діти роблять домашнє завдання.',null,null,null,null,null,null,array[]::text[],19006),
('a1-sch-08','A1','schule','a1-schule-1','phrase','In den Ferien fahren wir weg.','На каникулах мы уезжаем.','На канікулах ми кудись їдемо.',null,null,null,null,null,null,array['word_order_v2']::text[],19007),
('a1-sch-09','A1','schule','a1-schule-1','word','die Schule','школа','школа',null,'Die Schule ist nicht weit.','Школа недалеко.','Школа недалеко.','die','die Schulen',array[]::text[],19008),
('a1-sch-10','A1','schule','a1-schule-1','word','der Lehrer','учитель','учитель',null,'Der Lehrer heißt Herr Wagner.','Учителя зовут господин Вагнер.','Учителя звати пан Вагнер.','der','die Lehrer',array[]::text[],19009),
('a1-sch-11','A1','schule','a1-schule-1','word','die Lehrerin','учительница','учителька',null,'Ich schreibe der Lehrerin eine E-Mail.','Я пишу учительнице письмо.','Я пишу вчительці листа.','die','die Lehrerinnen',array['case_dativ']::text[],19010),
('a1-sch-12','A1','schule','a1-schule-1','word','die Kita','детский сад','дитячий садок',null,'Die Kita schließt um 16 Uhr.','Детский сад закрывается в 16 часов.','Дитсадок зачиняється о 16-й.','die','die Kitas',array[]::text[],19011),
('a1-sch-13','A1','schule','a1-schule-1','word','das Zeugnis','табель, аттестат','табель, атестат',null,'Im Juli gibt es Zeugnisse.','В июле выдают табели.','У липні видають табелі.','das','die Zeugnisse',array[]::text[],19012),
('a1-sch-14','A1','schule','a1-schule-1','word','die Ferien','каникулы (только мн. ч.)','канікули (лише мн.)',null,'Die Ferien sind leider vorbei.','Каникулы, к сожалению, закончились.','Канікули, на жаль, закінчилися.',null,'die Ferien',array[]::text[],19013)
