insert into public.content_items (id,level_id,topic_id,lesson_id,kind,de,ru,uk,cloze,example_de,example_ru,example_uk,article,plural,tags,sort) values
('a1-deu-01','A1','deutschland','a1-deutschland-1','phrase','Sonntags sind die Geschäfte zu.','По воскресеньям магазины закрыты.','У неділю магазини зачинені.',null,null,null,null,null,null,array[]::text[],21000),
('a1-deu-02','A1','deutschland','a1-deutschland-1','phrase','In Deutschland trennt man den Müll.','В Германии мусор сортируют.','У Німеччині сміття сортують.',null,null,null,null,null,null,array[]::text[],21001),
('a1-deu-03','A1','deutschland','a1-deutschland-1','phrase','Bei uns sagt man „Moin“.','У нас говорят «Мойн» (привет на севере).','У нас кажуть «Мойн» (привіт на півночі).',null,null,null,null,null,null,array[]::text[],21002),
('a1-deu-04','A1','deutschland','a1-deutschland-1','phrase','Pünktlichkeit ist hier sehr wichtig.','Пунктуальность здесь очень важна.','Пунктуальність тут дуже важлива.',null,null,null,null,null,null,array[]::text[],21003),
('a1-deu-05','A1','deutschland','a1-deutschland-1','phrase','Weihnachten feiern wir mit der Familie.','Рождество мы празднуем с семьёй.','Різдво ми святкуємо з родиною.',null,null,null,null,null,null,array['word_order_v2','case_dativ']::text[],21004),
('a1-deu-06','A1','deutschland','a1-deutschland-1','phrase','Die Pfandflasche bringe ich zurück in den Supermarkt.','Бутылку с залогом я сдаю обратно в супермаркет.','Пляшку із заставою я здаю назад у супермаркет.',null,null,null,null,null,null,array['word_order_v2']::text[],21005),
('a1-deu-07','A1','deutschland','a1-deutschland-1','phrase','Im Winter ist es oft grau und kalt.','Зимой часто серо и холодно.','Взимку часто сіро й холодно.',null,null,null,null,null,null,array[]::text[],21006),
('a1-deu-08','A1','deutschland','a1-deutschland-1','phrase','Wie ist das Wetter heute?','Какая сегодня погода?','Яка сьогодні погода?',null,null,null,null,null,null,array[]::text[],21007),
('a1-deu-09','A1','deutschland','a1-deutschland-1','phrase','Es regnet schon den ganzen Tag.','Дождь идёт уже весь день.','Дощ іде вже цілий день.',null,null,null,null,null,null,array[]::text[],21008),
('a1-deu-10','A1','deutschland','a1-deutschland-1','word','die Stadt','город','місто',null,'Köln ist eine große Stadt.','Кёльн — большой город.','Кельн — велике місто.','die','die Städte',array[]::text[],21009),
('a1-deu-11','A1','deutschland','a1-deutschland-1','word','das Bundesland','федеральная земля','федеральна земля',null,'Deutschland hat sechzehn Bundesländer.','В Германии шестнадцать федеральных земель.','У Німеччині шістнадцять федеральних земель.','das','die Bundesländer',array[]::text[],21010),
('a1-deu-12','A1','deutschland','a1-deutschland-1','word','das Wetter','погода','погода',null,'Das Wetter ist heute schön.','Погода сегодня хорошая.','Погода сьогодні гарна.','das',null,array[]::text[],21011),
('a1-deu-13','A1','deutschland','a1-deutschland-1','word','der Feiertag','праздничный день','святковий день',null,'Am Feiertag arbeite ich nicht.','В праздник я не работаю.','У свято я не працюю.','der','die Feiertage',array[]::text[],21012),
('a1-deu-14','A1','deutschland','a1-deutschland-1','word','der Nachbar','сосед','сусід',null,'Unser Nachbar ist sehr hilfsbereit.','Наш сосед очень отзывчивый.','Наш сусід дуже чуйний.','der','die Nachbarn',array[]::text[],21013),
('a1-deu-15','A1','deutschland','a1-deutschland-1','word','die Nachbarin','соседка','сусідка',null,'Die Nachbarin hat ein Paket für uns angenommen.','Соседка приняла для нас посылку.','Сусідка прийняла для нас посилку.','die','die Nachbarinnen',array['perfekt']::text[],21014)
